let appUrl = 'https://geo.griyaquran.web.id';
const n8nApiKey = 'ISI_N8N_API_KEY_APLIKASI_DI_SINI';
const gowaUrl = 'ISI_URL_GOWA_DI_SINI';

appUrl = String(appUrl).trim().replace(/\/+$/, '');
if (appUrl.toLowerCase().endsWith('/api')) appUrl = appUrl.slice(0, -4);
if (!/^https:\/\//i.test(appUrl)) throw new Error('Isi appUrl dengan URL HTTPS GeoPresensi.');
if (!n8nApiKey || n8nApiKey === 'ISI_N8N_API_KEY_APLIKASI_DI_SINI') throw new Error('Isi N8N_API_KEY aplikasi presensi.');
if (!/^https:\/\//i.test(String(gowaUrl).trim())) throw new Error('Isi gowaUrl dengan URL HTTPS endpoint GOWA.');

return [{ json: { appUrl, n8nApiKey, gowaUrl: String(gowaUrl).trim() } }];

const response = $input.first().json;
if (!response.success) throw new Error(response.message || 'Gagal mengambil status konfirmasi dari GeoPresensi.');
const result = response.data || {};
if (!result.active || !result.shouldSend) return [];
const cfg = $items('Konfigurasi')[0]?.json;
if (!cfg) throw new Error('Konfigurasi workflow tidak ditemukan.');
const teachers = Array.isArray(result.data) ? result.data : [];
const period = result.period?.label || 'bulan sebelumnya';
const appUrl = cfg.appUrl;
return teachers.flatMap((teacher) => {
  const phone = String(teacher.phone || '').replace(/[^0-9]/g, '');
  if (!phone || !teacher.nama) return [];
  const greeting = "Assalamu'alaikum Bapak/Ibu *" + String(teacher.nama).trim() + "*,";
  const message = [
    '🔔 *Pengingat Konfirmasi Rekap Presensi*',
    '',
    greeting,
    '',
    'Mohon tinjau dan konfirmasi rekap presensi periode *' + period + '* melalui aplikasi GeoPresensi.',
    '',
    'Jika ada data yang belum sesuai, ajukan koreksi sebelum memilih Setuju.',
    '👉 ' + appUrl,
    '',
    '_Pengingat ini berhenti setelah konfirmasi berhasil._',
    '_Sistem GeoPresensi Griya Quran_'
  ].join('\n');
  return [{ json: { nama: teacher.nama, phone, message, gowaUrl: cfg.gowaUrl } }];
});
